@namespace sv_027c0433179b4a5fba424b3256507059.Components.Pages.Catalog
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-container">
    <aside class="catalog-sidebar">
        <CatalogFilterPanel Categories="@_categories" OnFiltersApplied="HandleFiltersApplied" />
    </aside>

    <main class="catalog-main">
        @if (_error is not null)
        {
            <div class="alert alert-danger">@_error</div>
        }
        else if (_loading)
        {
            <div class="loading-indicator">Loading products...</div>
        }
        else if (_result is null || _result.Items.Count == 0)
        {
            <div class="empty-state">
                <p>No products found matching your criteria.</p>
            </div>
        }
        else
        {
            <div class="catalog-toolbar">
                <div class="sort-control">
                    <label for="sort-select">Sort by:</label>
                    <select id="sort-select" class="form-select" @onchange="HandleSortChanged">
                        <option value="price_asc" selected="@(_sortBy == "price_asc")">Price: Low to High</option>
                        <option value="price_desc" selected="@(_sortBy == "price_desc")">Price: High to Low</option>
                        <option value="name_asc" selected="@(_sortBy == "name_asc")">Name: A-Z</option>
                        <option value="rating_desc" selected="@(_sortBy == "rating_desc")">Rating: Highest</option>
                    </select>
                </div>
                <span class="results-info">
                    Showing @((_result.Page - 1) * _result.PageSize + 1)–@(Math.Min(_result.Page * _result.PageSize, _result.TotalCount)) of @_result.TotalCount products
                </span>
            </div>

            <div class="product-grid">
                @foreach (var product in _result.Items)
                {
                    <ProductCard Product="@product"
                                 OnProductSelected="HandleProductSelected"
                                 OnAddToCart="HandleAddToCart" />
                }
            </div>

            <nav class="pagination-controls" aria-label="Product pagination">
                <button class="btn btn-outline-secondary"
                        disabled="@(_currentPage <= 1)"
                        @onclick="() => GoToPage(_currentPage - 1)">
                    Previous
                </button>
                @for (int i = 1; i <= TotalPages; i++)
                {
                    var pageNum = i;
                    <button class="btn @(pageNum == _currentPage ? "btn-primary" : "btn-outline-secondary")"
                            @onclick="() => GoToPage(pageNum)">
                        @pageNum
                    </button>
                }
                <button class="btn btn-outline-secondary"
                        disabled="@(_currentPage >= TotalPages)"
                        @onclick="() => GoToPage(_currentPage + 1)">
                    Next
                </button>
            </nav>
        }
    </main>
</div>

