@page "/catalog"
@namespace sv_027c0433179b4a5fba424b3256507059.Components.Pages.Catalog
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-container">
    <aside class="catalog-sidebar">
        <CatalogFilterPanel Categories="@_categories" OnFiltersApplied="HandleFiltersApplied" />
    </aside>

    <main class="catalog-main">
        @if (_error is not null)
        {
            <div class="alert alert-danger">@_error</div>
        }
        else if (_loading)
        {
            <div class="loading-indicator">Loading products...</div>
        }
        else if (_result is null || _result.Items.Count == 0)
        {
            <div class="empty-state">
                <p>No products found matching your criteria.</p>
            </div>
        }
        else
        {
            <div class="catalog-toolbar">
                <div class="sort-control">
                    <label for="sort-select">Sort by:</label>
                    <select id="sort-select" class="form-select" @onchange="HandleSortChanged">
                        <option value="price_asc" selected="@(_sortBy == "price_asc")">Price: Low to High</option>
                        <option value="price_desc" selected="@(_sortBy == "price_desc")">Price: High to Low</option>
                        <option value="name_asc" selected="@(_sortBy == "name_asc")">Name: A-Z</option>
                        <option value="rating_desc" selected="@(_sortBy == "rating_desc")">Rating: Highest</option>
                    </select>
                </div>
                <span class="results-info">
                    Showing @((_result.Page - 1) * _result.PageSize + 1)–@(Math.Min(_result.Page * _result.PageSize, _result.TotalCount)) of @_result.TotalCount products
                </span>
            </div>

            <div class="product-grid">
                @foreach (var product in _result.Items)
                {
                    <ProductCard Product="@product"
                                 OnProductSelected="HandleProductSelected"
                                 OnAddToCart="HandleAddToCart" />
                }
            </div>

            <nav class="pagination-controls" aria-label="Product pagination">
                <button class="btn btn-outline-secondary"
                        disabled="@(_currentPage <= 1)"
                        @onclick="() => GoToPage(_currentPage - 1)">
                    Previous
                </button>
                @for (int i = 1; i <= TotalPages; i++)
                {
                    var pageNum = i;
                    <button class="btn @(pageNum == _currentPage ? "btn-primary" : "btn-outline-secondary")"
                            @onclick="() => GoToPage(pageNum)">
                        @pageNum
                    </button>
                }
                <button class="btn btn-outline-secondary"
                        disabled="@(_currentPage >= TotalPages)"
                        @onclick="() => GoToPage(_currentPage + 1)">
                    Next
                </button>
            </nav>
        }
    </main>
</div>

@code {
    private List<string>? _categories;
    private PagedResult<Product>? _result;
    private ProductFilter _filter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private const int PageSize = 12;
    private bool _loading = true;
    private string? _error;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private int TotalPages => _result is null || _result.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)_result.TotalCount / _result.PageSize);

    protected override async Task OnInitializedAsync()
    {
        await LoadDataAsync();
    }

    private async Task LoadDataAsync()
    {
        try
        {
            _loading = true;
            _error = null;

            var categoriesTask = _categories is null
                ? ProductService.GetCategoriesAsync()
                : Task.FromResult(_categories);
            var searchTask = ProductService.SearchAsync(_filter, _sortBy, _currentPage, PageSize);

            await Task.WhenAll(categoriesTask, searchTask);

            _categories = await categoriesTask;
            _result = await searchTask;
        }
        catch (Exception ex)
        {
            _error = $"An error occurred while loading products: {ex.Message}";
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task HandleFiltersApplied(ProductFilter filter)
    {
        _filter = filter;
        _currentPage = 1;
        await LoadDataAsync();
    }

    private async Task HandleSortChanged(ChangeEventArgs e)
    {
        _sortBy = e.Value?.ToString() ?? "price_asc";
        _currentPage = 1;
        await LoadDataAsync();
    }

    private async Task GoToPage(int page)
    {
        if (page < 1 || page > TotalPages) return;
        _currentPage = page;
        await LoadDataAsync();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        return Task.CompletedTask;
    }
}

